-- ════════════════════════════════════════════════════════
-- 219 — `brands.source` n'est plus un varchar(500)
-- ────────────────────────────────────────────────────────
-- CE QUI EST ARRIVE. `brands.source` etait un varchar(500). Les sources
-- ecrites depuis la migration 204 — un titre d'article, sa date, les
-- faits qu'il etablit, le second article, le site de la maison — font
-- souvent six a neuf cents caracteres. MySQL les a coupees a 500 SANS
-- ERREUR, exactement comme `moderation_log.detail` coupait a 255 : le
-- meme defaut, sur une autre colonne, un mois plus tard. 53 fiches
-- s'arretaient au milieu d'un mot, et les CONCAT des lots 5, 5 bis et
-- des requalifications ajoutaient a une valeur deja pleine — Drew
-- Estate n'a jamais recu sa note du lot 5 bis.
--
-- Decouvert par un controle de la 218 qui verifiait que treize sources
-- portaient « lot 5 bis : » — douze le portaient.
--
-- CE QUE FAIT CETTE MIGRATION. La colonne passe en TEXT. Puis chaque
-- source tronquee est reecrite dans sa version complete, reconstruite
-- depuis les generateurs (207 a 218) et les migrations ecrites a la main
-- (204 a 206), dans l'ordre ou elles ont ete posees puis prolongees. Le
-- generateur a verifie pour chacune que la valeur tronquee en base est
-- un PREFIXE de la valeur reconstruite : sinon il refuse d'ecrire.
--
-- Un test de campagne verifie desormais le type de la colonne, pour que
-- la production ne puisse pas rester en varchar(500).
-- ════════════════════════════════════════════════════════

ALTER TABLE `brands` MODIFY `source` TEXT NULL;

