DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 219';
INSERT INTO `moderation_log`
  (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES
  (NULL,'migration 219','systeme','source_varchar_500_tronquait','marque',0,
   'brands.source etait un varchar(500) : 53 fiches coupees a 500 caracteres sans erreur depuis la 204, comme detail coupait a 255. Colonne passee en TEXT, sources reconstruites depuis les generateurs, chaque tronquee verifiee prefixe de sa reconstruction');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE CHAR_LENGTH(`source`) = 500 AND `name` <> 'ADVentura') = 0 AS plus_aucune_a_500,
  (SELECT COUNT(*) FROM `brands` WHERE CHAR_LENGTH(`source`) > 500) >= 52 AS reconstruites,
  (SELECT DATA_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'brands' AND COLUMN_NAME = 'source') = 'text' AS colonne_text,
  (SELECT `source` LIKE '%lot 5 bis :%' FROM `brands` WHERE `name` = 'Drew Estate') AS drew_estate_complete;
